script:
set -eu
fail() { printf '%s\n' 'Cannot read private fleetd configuration' >&2; exit 1; }
case "$(uname -s)" in
  Linux) directory=${XDG_CONFIG_HOME-$HOME/.config}/ctlflow; format='%u %a %h %s';;
  Darwin) directory=$HOME/Library/'Application Support'/ctlflow; format='%u %Lp %l %z';;
  *) fail;;
esac
case $directory in /*) ;; *) fail;; esac
[ "$(cd -P -- "$directory" && pwd -P)" = "$directory" ] || fail
file=$directory/fleetd.json
[ -f "$file" ] && [ ! -L "$file" ] || fail
uid=$(id -u)
case "$(uname -s)" in
  Linux) metadata=$(stat -c "$format" -- "$directory");;
  Darwin) metadata=$(stat -f "$format" "$directory");;
esac
set -- $metadata
[ "$1" = "$uid" ] && [ $((0$2 & 077)) -eq 0 ] || fail
exec 3<"$file"
case "$(uname -s)" in
  Linux) metadata=$(stat -L -c "$format" /proc/$$/fd/3);;
  Darwin) metadata=$(stat -L -f "$format" /dev/fd/3);;
esac
set -- $metadata
[ "$1" = "$uid" ] && [ $((0$2 & 077)) -eq 0 ] && [ "$3" = 1 ] && [ "$4" -gt 0 ] && [ "$4" -le 4096 ] || fail
head -c 4097 <&3
